export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId | null,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

/** Sessions whose default workspace is `orgId`, optionally for a single user. */
export async function listSessionsByActiveOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly { id: SessionId; userId: UserId }[]> {
  const filters = [eq(sessions.activeOrgId, orgId)];
  if (userId !== undefined) filters.push(eq(sessions.userId, userId));

  const rows = getDb()
    .select({ id: sessions.id, userId: sessions.userId })
    .from(sessions)
    .where(and(...filters))
    .all();

  return rows.map((row) => ({
    id: brandId<SessionId>(row.id),
    userId: brandId<UserId>(row.userId),
  }));
}

