/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

type NormalizedInvite = {
  email: string;
  role: InviteMembersInput["invites"][number]["role"];
};

/**
 * Refuses the whole batch when an address is repeated, already belongs to a
 * current member, or already has a pending invitation. Comparison ignores case.
 * A former member, and an address whose earlier invitation expired or was
 * revoked, can be invited again.
 */
async function assertInvitesAreOpen(
  orgId: OrgId,
  invites: readonly { email: string; role: NormalizedInvite["role"] }[],
): Promise<readonly NormalizedInvite[]> {
  const normalized = invites.map((invite) => ({
    email: normalizeEmail(invite.email),
    role: invite.role,
  }));

  const seen = new Set<string>();
  for (const invite of normalized) {
    if (seen.has(invite.email)) {
      throw new Error(
        `An invitation batch cannot name the same address twice (${invite.email})`,
      );
    }
    seen.add(invite.email);
  }

  const pending = await invitationRepo.listPendingInvitations(orgId);
  const pendingEmails = new Set(pending.map((row) => normalizeEmail(row.email)));

  for (const invite of normalized) {
    if (pendingEmails.has(invite.email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }

    const user = await userRepo.findUserByEmail(invite.email);
    if (user) {
      const member = await memberRepo.findMember(orgId, user.id);
      if (member) {
        throw new Error(`${invite.email} is already a member of this workspace`);
      }
    }
  }

  return normalized;
}

