 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, OrgId, UserId } from "@/types/common";
import type { Actor, Invitation, Member, Role } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

type NormalizedInvite = {
  email: string;
  role: InviteMembersInput["invites"][number]["role"];
};

/**
 * Refuses the whole batch when an address is repeated, already belongs to a
 * current member, or already has a pending invitation. Comparison ignores case.
 * A former member, and an address whose earlier invitation expired or was
 * revoked, can be invited again.
 */
async function assertInvitesAreOpen(
  orgId: OrgId,
  invites: readonly { email: string; role: NormalizedInvite["role"] }[],
): Promise<readonly NormalizedInvite[]> {
  const normalized = invites.map((invite) => ({
    email: normalizeEmail(invite.email),
    role: invite.role,
  }));

  const seen = new Set<string>();
  for (const invite of normalized) {
    if (seen.has(invite.email)) {
      throw new Error(
        `An invitation batch cannot name the same address twice (${invite.email})`,
      );
    }
    seen.add(invite.email);
  }

  const pending = await invitationRepo.listPendingInvitations(orgId);
  const pendingEmails = new Set(pending.map((row) => normalizeEmail(row.email)));

  for (const invite of normalized) {
    if (pendingEmails.has(invite.email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }

    const user = await userRepo.findUserByEmail(invite.email);
    if (user) {
      const member = await memberRepo.findMember(orgId, user.id);
      if (member) {
        throw new Error(`${invite.email} is already a member of this workspace`);
      }
    }
  }

  return normalized;
}

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const invites = await assertInvitesAreOpen(input.orgId, input.invites);

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId));

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That invitation's workspace no longer exists");
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (normalizeEmail(user.email) !== normalizeEmail(invitation.email)) {
    throw new Error("Only the invited account can accept this invitation");
  }

  const now = toIsoTimestamp(new Date());
  const prior = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );

  let member: Member;
  if (prior && prior.archivedAt === null) {
    member = prior;
  } else if (prior) {
    member = await memberRepo.restoreMember(
      invitation.orgId,
      prior.id,
      invitation.role,
      invitation.invitedBy,
      now,
    );
  } else {
    member = await memberRepo.insertMember(
      invitation.orgId,
      userId,
      invitation.role,
      invitation.invitedBy,
    );
  }

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);

  // A person who is already a live member already occupies a seat and has
  // already been announced. Rejoining, like a first join, tells the owner.
  if (!prior || prior.archivedAt !== null) {
    await emit("member.joined", {
      ...envelope(invitation.orgId, userId),
      memberId: member.id,
      userId,
      role: member.role,
    });
  }

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Withdraws the old link and issues a new one to the same address with the
 * same role, valid for 14 days from the re-send. An expired invitation can be
 * re-sent; that is the usual reason to re-send one.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (previous.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (previous.role === "owner") {
    throw new Error("Ownership is transferred, not re-invited");
  }

  const role: Exclude<Role, "owner"> = previous.role;

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role,
  });
}
