input.new_string:
import type { SwitchOrgInput } from "@/schemas/session";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Actor, SessionPrincipal } from "@/types/member";

/**
 * Stops sessions from opening on a workspace the person can no longer use.
 * Sessions that already default to a different workspace are left alone. When
 * the user still belongs to another workspace, the session defaults to that
 * one; otherwise the default is cleared. Pass `userId` to limit the change to
 * that person's sessions.
 */
export async function releaseDefaultOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<void> {
  const affected = await sessionRepo.listSessionsByActiveOrg(orgId, userId);
  const fallbackByUser = new Map<UserId, OrgId | null>();

  for (const session of affected) {
    let fallback = fallbackByUser.get(session.userId);
    if (fallback === undefined) {
      fallback = await fallbackOrgFor(session.userId, orgId);
      fallbackByUser.set(session.userId, fallback);
    }
    await sessionRepo.setActiveOrg(session.id, fallback);
  }
}

async function fallbackOrgFor(
  userId: UserId,
  leavingOrgId: OrgId,
): Promise<OrgId | null> {
  const orgs = await orgRepo.listOrgsForUser(userId);
  for (const org of orgs) {
    if (org.id === leavingOrgId) continue;
    const member = await memberRepo.findMember(org.id, userId);
    if (member && member.status === "active") return org.id;
  }
  return null;
}

