describe("invitation behaviour", () => {
  it("covers the reported cases", async () => {
    const tenant = await createTenant("cases", "growth");
    const admin = tenant.actors.admin;

    const created = await invitationService.inviteMember(admin, {
      orgId: tenant.org.id,
      email: "New.Person@cases.test",
      role: "admin",
    });
    const lifetime = Date.parse(created.expiresAt) - Date.parse(created.createdAt);
    expect(lifetime).toBeGreaterThan(13 * 24 * 60 * 60 * 1000);
    expect(lifetime).toBeLessThan(15 * 24 * 60 * 60 * 1000);
    expect(created.email).toBe("new.person@cases.test");

    await expect(
      invitationService.inviteMembers(admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "new.person@cases.test", role: "viewer" },
          { email: "other@cases.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/pending/i);
    await expect(invitationRepo.countPendingInvitations(tenant.org.id)).resolves.toBe(1);

    await expect(
      invitationService.inviteMembers(admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "dup@cases.test", role: "member" },
          { email: "DUP@cases.test", role: "viewer" },
        ],
      }),
    ).rejects.toThrow(/twice/i);
    await expect(invitationRepo.countPendingInvitations(tenant.org.id)).resolves.toBe(1);

    await expect(
      invitationService.inviteMember(admin, {
        orgId: tenant.org.id,
        email: "MEMBER@cases.test",
        role: "viewer",
      }),
    ).rejects.toThrow(/already a member/i);

    const expired = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "old@cases.test",
        role: "viewer",
        expiresInDays: -1,
      },
      tenant.userIds.admin,
      hashToken("e".repeat(32)),
    );
    await invitationRepo.revokeInvitation(tenant.org.id, created.id);
    expect(await invitationRepo.listPendingInvitations(tenant.org.id)).toEqual([]);
    expect(await invitationRepo.countPendingInvitations(tenant.org.id)).toBe(0);

    await invitationService.inviteMember(admin, {
      orgId: tenant.org.id,
      email: "old@cases.test",
      role: "member",
    });
    expect(await invitationRepo.countPendingInvitations(tenant.org.id)).toBe(1);

    const resent = await invitationService.resendInvitation(admin, expired.id);
    expect(resent.role).toBe("viewer");
    expect(resent.id).not.toBe(expired.id);
    const resentLife = Date.parse(resent.expiresAt) - Date.now();
    expect(resentLife).toBeGreaterThan(13 * 24 * 60 * 60 * 1000);
    await expect(
      invitationService.acceptInvitation(tenant.userIds.member, { token: "e".repeat(32) }),
    ).rejects.toThrow(/revoked/i);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("viewer missing");
    const other = await orgService.createOrganization(tenant.userIds.viewer, {
      name: "Other",
      slug: "other-cases",
      plan: "free",
    });
    const expiresAt = toIsoTimestamp(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000));
    const kept = await sessionRepo.createSession(tenant.userIds.viewer, hashToken("s".repeat(32)), expiresAt);
    const moved = await sessionRepo.createSession(tenant.userIds.viewer, hashToken("t".repeat(32)), expiresAt);
    const stranger = await sessionRepo.createSession(tenant.userIds.member, hashToken("u".repeat(32)), expiresAt);
    const keptRow = await sessionRepo.findSessionByTokenHash(hashToken("s".repeat(32)));
    const movedRow = await sessionRepo.findSessionByTokenHash(hashToken("t".repeat(32)));
    const strangerRow = await sessionRepo.findSessionByTokenHash(hashToken("u".repeat(32)));
    if (!keptRow || !movedRow || !strangerRow) throw new Error("session missing");
    void kept;
    void moved;
    void stranger;
    const sessions = await import("@/server/db").then((m) => m.getDb());
    const { sessions: sessionTable } = await import("@/server/db");
    const { eq } = await import("drizzle-orm");
    const all = sessions.select().from(sessionTable).all();
    const byHash = new Map(all.map((row) => [row.tokenHash, row]));
    const keptId = byHash.get(hashToken("s".repeat(32)))?.id;
    const movedId = byHash.get(hashToken("t".repeat(32)))?.id;
    const strangerId = byHash.get(hashToken("u".repeat(32)))?.id;
    if (!keptId || !movedId || !strangerId) throw new Error("ids");
    await sessionRepo.setActiveOrg(keptId as never, other.id);
    await sessionRepo.setActiveOrg(movedId as never, tenant.org.id);
    await sessionRepo.setActiveOrg(strangerId as never, tenant.org.id);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_created",
      inApp: true,
      email: true,
      digestOnly: true,
    });

    await memberService.removeMember(admin, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    const afterRemove = sessions.select().from(sessionTable).all();
    const afterMap = new Map(afterRemove.map((row) => [row.tokenHash, row]));
    expect(afterMap.get(hashToken("t".repeat(32)))?.activeOrgId).toBe(other.id);
    expect(afterMap.get(hashToken("s".repeat(32)))?.activeOrgId).toBe(other.id);
    expect(afterMap.get(hashToken("u".repeat(32)))?.activeOrgId).toBe(tenant.org.id);

    const notes = await notify(tenant.org.id, "comment_created", [tenant.userIds.viewer], {
      title: "still here?",
      body: "no",
      href: "/x",
      actorId: null,
    });
    expect(notes).toHaveLength(0);
    expect(await listDigestRecipients(tenant.org.id)).not.toContain(tenant.userIds.viewer);

    const rejoinedInvite = await invitationService.inviteMember(admin, {
      orgId: tenant.org.id,
      email: "viewer@cases.test",
      role: "admin",
    });
    const raw = "r".repeat(32);
    await invitationRepo.revokeInvitation(tenant.org.id, rejoinedInvite.id);
    const open = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "viewer@cases.test",
        role: "admin",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(raw),
    );

    const wrong = await userRepo.insertUser({
      email: "intruder@cases.test",
      name: "Intruder",
      passwordHash: "seed",
    });
    await expect(
      invitationService.acceptInvitation(wrong.id, { token: raw }),
    ).rejects.toThrow(/invited account/i);
    expect((await invitationRepo.findInvitationById(tenant.org.id, open.id))?.acceptedAt).toBeNull();

    const restored = await invitationService.acceptInvitation(tenant.userIds.viewer, {
      token: raw,
    });
    expect(restored.id).toBe(viewer.id);
    expect(restored.role).toBe("admin");
    expect(restored.status).toBe("active");
    expect(restored.archivedAt).toBeNull();
    expect(restored.invitedBy).toBe(tenant.userIds.admin);
    expect(restored.joinedAt).toBe(open.acceptedAt ?? restored.joinedAt);
    const fresh = await invitationRepo.findInvitationById(tenant.org.id, open.id);
    expect(restored.joinedAt).toBe(fresh?.acceptedAt);
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);
    expect(await memberService.resolveActor(tenant.userIds.viewer, tenant.org.id)).toMatchObject({
      role: "admin",
    });
    expect(await listDigestRecipients(tenant.org.id)).toContain(tenant.userIds.viewer);

    await orgRepo.archiveOrg(tenant.org.id);
    const late = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "new.person@cases.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken("z".repeat(32)),
    );
    const person = await userRepo.insertUser({
      email: "new.person@cases.test",
      name: "New",
      passwordHash: "seed",
    });
    await expect(
      invitationService.acceptInvitation(person.id, { token: "z".repeat(32) }),
    ).rejects.toThrow(/no longer exists/i);
    expect((await invitationRepo.findInvitationById(tenant.org.id, late.id))?.acceptedAt).toBeNull();

    await sessionRepo.setActiveOrg(strangerId as never, tenant.org.id);
    await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    const afterDelete = sessions
      .select()
      .from(sessionTable)
      .where(eq(sessionTable.id, strangerId))
      .get();
    expect(afterDelete?.activeOrgId).not.toBe(tenant.org.id);
  });
});
